from pwn import *

# Enable verbose logging
context.log_level = 'debug'

class GameAnalyzer:
    def __init__(self, is_remote=False):
        if is_remote:
            self.p = remote("rev.chal.csaw.io", 5000)
        else:
            self.p = process("./ctf_files/game")

    def make_choice(self, choice):
        self.p.recvuntil(b"Choice: ")
        self.p.sendline(str(choice).encode())
        return self.p.recvuntil(b"Choice: ", timeout=1)

    def try_password(self, password):
        print(f"\nTrying password: {password}")
        # Navigate to password door
        response = self.make_choice(2)  # center path

        if b"password in decimal form?:" in response:
            # Convert password to decimal form as required
            decimal_pass = int.from_bytes(password.encode(), 'big')
            self.p.sendline(str(decimal_pass).encode())
            response = self.p.recvuntil(b"Choice:", timeout=1)
            print(f"Response for {password}: {response}")

        return response

    def analyze(self, passwords):
        for password in passwords:
            try:
                response = self.try_password(password)
                if b"flag{" in response:
                    print(f"Found flag with password {password}!")
                    print(response)
            except EOFError:
                print(f"Connection closed for password {password}")
            except Exception as e:
                print(f"Error for password {password}: {e}")

def main():
    passwords = ["cook", "flawed", "gravel", "king", "decisive"]

    print("Testing local binary...")
    analyzer = GameAnalyzer(is_remote=False)
    analyzer.analyze(passwords)
    analyzer.p.close()

    print("\nTesting remote server...")
    analyzer = GameAnalyzer(is_remote=True)
    analyzer.analyze(passwords)
    analyzer.p.close()

if __name__ == "__main__":
    main()

